  "loc.enterShopAddressesUnder": "Kauppojen osoitteet annetaan kohdassa Listat → Muokkaa ostoslistaa – jos kauppa on useammassa paikassa, myös useita toimipisteitä. Jos joku viipyy siellä jonkin aikaa, suunniteltu ostosreissu merkitään tehdyksi.",
