  "loc.gpsTracker": "🛰️ GPS-seurantalaite",
  "loc.guide1": "Asenna sovellus <b>”Traccar Client”</b> (App Store tai Google Play, ilmainen).",
  "loc.guide2": "Anna sovelluksessa kohtaan <b>Device ID</b> (laitetunnus):",
  "loc.guide3": "Anna kohtaan <b>Server URL</b>:",
  "loc.guide4": "Tarkkuus <b>Medium</b>, etäisyys <b>50 m</b>. Sovellus lähettää silloin vain liikkuessasi – ei mitään paikallaan ollessa. Jos sinulla on lisää kenttiä (väli, heartbeat), aseta heartbeat pois tai arvoon 0.",
  "loc.guide5": "Salli sijainnin käyttö: <b>Aina</b> ja <b>Tarkka sijainti</b> päälle.",
  "loc.guide6": "Kytke <b>Service / Tracking</b> -kytkin päälle ja <b>jätä se aina päälle</b> – valmis. Tästä lähtien hallitset kaikkea pinn.:ssä: ”Lähetä jatkuvasti” päälle tai pois, ”Lähetä kerran” ja SOS. Niin kauan kuin ”Lähetä jatkuvasti” on pois päältä, kukaan ei näe sijaintiasi eikä pinn. tallenna reittiä.",
  "loc.guideIntro": "Ilman muuta sovellusta ”📍 Jaa sijainti” toimii suoraan pinn.:ssä – mutta vain, kun pinn. on auki. Jotta sijainti saapuu myös silloin, kun pinn. on suljettu ja näyttö lukittu, ilmainen ”Traccar Client” -sovellus lähettää sen suoraan pinn.:lle (Traccar-palvelinta ei tarvita). Sama iPhonelle ja Androidille.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. Tämä portti täytyy ohjata NAS-laitteelle FRITZ!Boxissa, koska seurantalaite ottaa yhteyden matkapuhelinverkosta.",
