  "loc.setupIntro": "Puhelimet eivät tarvitse mitään muuta: jokainen voi jakaa suoraan pinn.:ssä kohdassa ”Oma sijaintini”. Taustalla (pinn. suljettu) puhelin lähettää ilmaisella ”Traccar Client” -sovelluksella (iPhone ja Android) – suoraan pinn.:lle, Traccar-palvelinta ei tarvita. Vain SIM-korttiset GPS-seurantalaitteet (esim. pannassa) tarvitsevat ”traccar”-kontin. Sijainnit pysyvät NAS-laitteellasi.",
