  "settings.outlook.intro": "Joka sunnuntai klo 18 alkaen on viikkoennakko kaikesta tärkeästä tulevalla viikolla ja kuun viimeisenä päivänä klo 18 alkaen ennuste seuraavan kuun taloudesta. Molemmat näkyvät kerran ilmoituksena ylhäällä ja push-ilmoituksena – voit avata ne täällä uudelleen milloin tahansa.",
